            new Quote { Id = "https://ru.wikiquote.org/wiki/Виктор_Астафьев", Text = "Только в молодости человек может позволить себе быть глупым. В старости — это уже стыдно.", Author = "Виктор Астафьев" },
            new Quote { Id = "https://ru.wikiquote.org/wiki/Виктор_Астафьев", Text = "Жизнь — это река. Она течёт, и её нельзя остановить. Можно только плыть по течению.", Author = "Виктор Астафьев" },
